// Generate ONLY the locally-scoped PUBLIC browser key from Supabase CLI.
// The generated file is gitignored. Never store the service role key in JS.
import { writeFileSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import { loadLocalSupabase } from "./local-supabase-env.mjs";

const root = resolve(import.meta.dirname, "..");
const {api, publicKey} = loadLocalSupabase();
if (!api.startsWith("http://127.0.0.1:")) throw Error("Remote URL forbidden");
const file = resolve(root, "js", "rede-local-config.mjs");
mkdirSync(resolve(root,"js"),{recursive:true});
writeFileSync(file,
  "// Generated by scripts/local-prepare.mjs; DO NOT COMMIT.\n"+
  "export const url = "+JSON.stringify(api)+";\n"+
  "export const key = "+JSON.stringify(publicKey)+";\n", {mode:0o600});
console.log("Configuração pública LOCAL criada em js/rede-local-config.mjs.");
console.log("API restrita à origem 127.0.0.1; nenhuma chave administrativa foi gravada.");
